select category, case when stock_qty >= 346 then 'high' when stock_qty >= 191 then 'mid' else 'low' end as stock_qty_bucket, round((100 * sum(case when category = 'Home' then 1 else 0 end)) / count(*), 1) as pct_home, count(distinct price) as unique_brands from products where (cost is not null and price >= 460) or stock_qty = 350 group by 1, 2 having min(price) > 880 order by category;
